  'seed-103',
  (SELECT id FROM public.companies WHERE slug = 'gitlab'),
  'GitLab', 'Analytics Engineer Senior', 'analytics engineer senior',
  (SELECT id FROM public.career_tracks WHERE key = 'data_engineer'),
