SELECT (SELECT id FROM public.job_sources WHERE key = 'ashby_boards'),
  'seed-118',
  (SELECT id FROM public.companies WHERE slug = 'gympass'),
  'Gympass', 'Analytics Engineer Staff', 'analytics engineer staff',
