INSERT INTO public.salary_observations (job_posting_id, track_id, seniority, market_segment, country, currency, amount_min, amount_max, period, source, observed_at)
SELECT p.id, p.track_id, p.seniority, p.market_segment, p.country, p.salary_currency, p.salary_min, p.salary_max, p.salary_period, 'posting', COALESCE(p.posted_at, now())
FROM public.job_postings p
WHERE p.external_id = 'seed-150' AND p.source_id = (SELECT id FROM public.job_sources WHERE key = 'greenhouse_boards')
  AND NOT EXISTS (SELECT 1 FROM public.salary_observations so WHERE so.job_posting_id = p.id AND so.source = 'posting');
COMMIT;